FeatureScript 3112;
import(path : "onshape/std/geometry.fs", version : "3112.0");

// Fixture batch 040: ruled surfaces with vertex overrides on curved edges. Generated by tools/fixtures/gen-batch-040.mjs; do not edit.
// Each case builds its geometry at the origin and may return a map of values to check.

function round6(v) returns array
{
    return [roundToPrecision(v[0] / millimeter, 6), roundToPrecision(v[1] / millimeter, 6), roundToPrecision(v[2] / millimeter, 6)];
}

// Each face of a case's sheets: its area, its surface's type, and for a B-spline its degrees, knots and poles.
function sheetProbe(context is Context, sheets is Query) returns array
{
    var out = [];
    for (var face in evaluateQuery(context, qOwnedByBody(sheets, EntityType.FACE)))
    {
        const s = evSurfaceDefinition(context, { "face" : face });
        var entry = { "area" : roundToPrecision(evArea(context, { "entities" : face }) / millimeter ^ 2, 6), "type" : s.surfaceType };
        if (s is BSplineSurface)
        {
            var rows = [];
            for (var row in s.controlPoints)
                rows = append(rows, mapArray(row, round6));
            entry.bspline = { "uDegree" : s.uDegree, "vDegree" : s.vDegree, "rational" : s.isRational,
                              "uKnots" : mapArray(s.uKnots, function(k) { return roundToPrecision(k, 9); }),
                              "vKnots" : mapArray(s.vKnots, function(k) { return roundToPrecision(k, 9); }), "poles" : rows };
            if (s.isRational)
                entry.bspline.weights = s.weights;
        }
        out = append(out, entry);
    }
    return out;
}

// ruled-surface: normal to a round from its top arc, 5 mm wide but 10 mm at one end
export function c001(context is Context, id is Id)
{
    const baseSketch = newSketchOnPlane(context, id + "baseSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(baseSketch, "rect1", { "firstCorner" : vector(0, 0) * millimeter, "secondCorner" : vector(30, 20) * millimeter });
    skSolve(baseSketch);
    extrude(context, id + "base", { "entities" : qSketchRegion(id + "baseSketch"), "endBound" : BoundingType.BLIND, "depth" : 10 * millimeter });
    fillet(context, id + "round1", { "entities" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.EDGE), vector(30, 0, 5) * millimeter), "radius" : 10 * millimeter });
    ruledSurface(context, id + "ruled1", { "edges" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.EDGE), vector(27.071068, 2.928932, 10) * millimeter), "ruledType" : RuledSurfaceInterfaceType.NORMAL, "distance" : 5 * millimeter, "referenceFaces" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.FACE), vector(27.071068, 2.928932, 5) * millimeter), "vertexOverrides" : [{ "vertex" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.VERTEX), vector(30, 10, 10) * millimeter), "angleOverride" : 0 * degree, "oppositeAngleOverride" : false, "distanceOverride" : 10 * millimeter, "oppositeDirectionOverride" : false, "overrideType" : VertexOverrideType.NORMAL }] });
    return { "faces" : sheetProbe(context, qBodyType(qCreatedBy(id + "ruled1", EntityType.BODY), BodyType.SHEET)) };
}

